const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================================\n// PRISMA SCHEMA - Better Auth Organization Plugin Optimized\n// School Management System for Ghana Basic Schools\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// BETTER AUTH CORE MODELS\n// These are required by Better Auth and should not be modified\n// ============================================================================\n\n// ============================================================\n// BETTER AUTH CORE MODELS\n// Better Auth's prisma adapter expects these exact model names:\n// user, session, account, verification\n// The organization plugin expects: organization, member, invitation\n// We keep @@map() to preserve existing table names in the DB.\n// ============================================================\n\nmodel user {\n  id            String    @id\n  name          String\n  email         String    @unique\n  emailVerified Boolean   @default(false)\n  image         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n  // Global role field — intentionally kept for superAdmin to manage all orgs.\n  // All other role-based access is handled via Better Auth organization member roles.\n  role          String    @default(\"user\")\n  banned        Boolean   @default(false)\n  banReason     String?\n  banExpires    DateTime?\n\n  // Relations\n  accounts           account[]\n  sessions           session[]\n  invitations        invitation[]\n  members            member[]\n  attendancesMarked  Attendance[]           @relation(\"AttendanceMarkedBy\")\n  auditLogs          AuditLog[]\n  componentScores    ComponentScore[]\n  documents          Document[]\n  gradingSystems     GradingSystem[]\n  paymentsRecorded   Payment[]              @relation(\"PaymentRecordedBy\")\n  transcriptRequests TranscriptRequest[]\n  notifications      Notification[]\n  announcementsSent  Announcement[]         @relation(\"AnnouncementsSent\")\n  expensesRecorded   Expense[]              @relation(\"ExpenseRecordedBy\")\n  inventoryPerformed InventoryTransaction[] @relation(\"InventoryPerformedBy\")\n  inventoryReceived  InventoryTransaction[] @relation(\"InventoryRecipient\")\n  userProfile        UserProfile?\n  submittedTickets   SupportTicket[]        @relation(\"SubmittedTickets\")\n  assignedTickets    SupportTicket[]        @relation(\"AssignedTickets\")\n  ticketReplies      TicketReply[]\n  payrollProcessed   PayrollRecord[]        @relation(\"PayrollProcessedBy\")\n  promotionsApproved PromotionRecord[]      @relation(\"PromotedBy\")\n\n  @@index([banned])\n  @@index([email])\n  @@index([role])\n  @@map(\"users\")\n}\n\nmodel session {\n  id                   String   @id\n  expiresAt            DateTime\n  token                String   @unique\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n  ipAddress            String?\n  userAgent            String?\n  userId               String\n  // Required by the organization plugin — tracks which org the user is viewing\n  activeOrganizationId String?\n  // Required by impersonation (admin plugin)\n  impersonatedBy       String?\n\n  user user @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([token])\n  @@index([userId])\n  @@index([activeOrganizationId])\n  @@index([impersonatedBy])\n  @@map(\"sessions\")\n}\n\nmodel account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  user user @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([providerId, accountId])\n  @@index([userId])\n  @@map(\"accounts\")\n}\n\nmodel verification {\n  id         String   @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([identifier, value])\n  @@index([identifier])\n  @@index([expiresAt])\n  @@map(\"verifications\")\n}\n\n// ============================================================\n// BETTER AUTH ORGANIZATION PLUGIN MODELS\n// Model names must be exactly: organization, member, invitation\n// ============================================================\n\nmodel organization {\n  id        String   @id\n  name      String\n  slug      String   @unique\n  logo      String?\n  // metadata must be String (JSON stored as text) per Better Auth's schema\n  metadata  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  members     member[]\n  invitations invitation[]\n  school      School?\n  roles       organizationRole[]\n\n  // Subscription State (Better Auth Customization)\n  subscriptionStatus String    @default(\"TRIALING\") // Use String for Better Auth compatibility if needed, else Enum\n  expiresAt          DateTime?\n\n  @@index([slug])\n  @@index([subscriptionStatus])\n  @@map(\"organizations\")\n}\n\n// ============================================================\n// BETTER AUTH DYNAMIC ACCESS CONTROL\n// Required by the organization plugin when dynamicAccessControl is enabled.\n// Stores custom roles created at runtime per organization.\n// ============================================================\n\nmodel organizationRole {\n  id             String   @id\n  organizationId String\n  role           String\n  permissions    String // JSON string of permission map e.g. {\"student\":[\"view\",\"create\"]}\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, role])\n  @@index([organizationId])\n  @@map(\"organization_roles\")\n}\n\nmodel member {\n  id             String   @id\n  organizationId String\n  userId         String\n  role           String\n  banned         Boolean  @default(false)\n  banReason      String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user         user         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, userId])\n  @@index([organizationId])\n  @@index([userId])\n  @@index([role])\n  @@map(\"members\")\n}\n\nmodel invitation {\n  id             String   @id\n  organizationId String\n  email          String\n  role           String?\n  status         String   @default(\"pending\")\n  expiresAt      DateTime\n  createdAt      DateTime @default(now())\n  inviterId      String\n\n  organization organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  inviter      user         @relation(fields: [inviterId], references: [id], onDelete: Cascade)\n\n  @@index([email])\n  @@index([inviterId])\n  @@index([organizationId])\n  @@index([status])\n  @@map(\"invitations\")\n}\n\n// ============================================================\n// APPLICATION MODELS\n// These reference `user` (singular) to match the Better Auth model.\n// ============================================================\n\nmodel School {\n  id             String   @id @default(cuid())\n  // One-to-one with organization — the org IS the school's auth boundary\n  organizationId String   @unique\n  name           String\n  code           String   @unique\n  email          String?\n  phone          String?\n  address        String?\n  logo           String?\n  motto          String?\n  website        String?\n  subdomain      String   @unique\n  currency       String   @default(\"GHS\")\n  timezone       String   @default(\"Africa/Accra\")\n  locale         String   @default(\"en-GH\")\n  primaryColor   String   @default(\"#3B82F6\")\n  secondaryColor String   @default(\"#10B981\")\n  settings       Json?\n  features       Json?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization                organization                @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  academicYears               AcademicYear[]\n  assessmentTemplates         AssessmentTemplate[]\n  bills                       Bill[]\n  chartAccounts               ChartAccount[]\n  classes                     Class[]\n  customExpenseCategories     CustomExpenseCategory[]\n  customFeeCategories         CustomFeeCategory[]\n  customTransactionCategories CustomTransactionCategory[]\n  departments                 Department[]\n  documents                   Document[]\n  feeStructures               FeeStructure[]\n  gradingSystems              GradingSystem[]\n  guardians                   Guardian[]\n  houses                      House[]\n  payments                    Payment[]\n  staff                       Staff[]\n  students                    Student[]\n  subjects                    Subject[]\n  subscription                Subscription?\n  teachers                    Teacher[]\n  transactions                Transaction[]\n  reportCardTemplates         ReportCardTemplate[]\n  reportCardSets              ReportCardSet[]\n  notifications               Notification[]\n  announcements               Announcement[]\n  expenses                    Expense[]\n  inventoryItems              InventoryItem[]\n  inventoryTransactions       InventoryTransaction[]\n  supportTickets              SupportTicket[]\n  clubs                       Club[]\n  payrollRecords              PayrollRecord[]\n  payslips                    Payslip[]\n  classrooms                  Classroom[]\n  timeSlots                   TimeSlot[]\n  periodTemplates             PeriodTemplate[]\n  timetableEntries            TimetableEntry[]\n\n  // Advanced Accounting Registries\n  feeItemRegistry     FeeItemRegistry[]\n  expenditureRegistry ExpenditureCategoryRegistry[]\n  teacherAssignments  TeacherAssignment[]\n  staffAssignments    StaffAssignment[]\n  promotionRecords    PromotionRecord[]\n  auditLogs           AuditLog[]\n\n  @@index([code])\n  @@index([subdomain])\n  @@index([organizationId])\n  @@map(\"schools\")\n}\n\n// ============================================================================\n// USER PROFILES & ROLES\n// ============================================================================\n\nmodel UserProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  // Personal Information\n  firstName      String\n  lastName       String\n  otherNames     String?\n  phone          String?\n  alternatePhone String?\n  gender         Gender\n  dateOfBirth    DateTime @db.Date\n\n  // Address Information\n  nationality        String? @default(\"Ghanaian\")\n  residentialAddress String?\n  postalAddress      String?\n  city               String?\n  region             String?\n  country            String? @default(\"Ghana\")\n\n  // Emergency Contact\n  emergencyContactName  String?\n  emergencyContactPhone String?\n  emergencyRelationship String?\n  isActive              Boolean   @default(true)\n  lastLoginAt           DateTime?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  user      user       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  guardians Guardian[] // One profile can be linked to guardians at multiple schools\n  staff     Staff?\n  student   Student?\n  teacher   Teacher?\n\n  @@index([userId])\n  @@index([isActive])\n  @@map(\"user_profiles\")\n}\n\nmodel Student {\n  id                 String        @id @default(cuid())\n  profileId          String        @unique\n  schoolId           String\n  studentId          String\n  admissionNumber    String?\n  admissionDate      DateTime      @default(now()) @db.Date\n  classId            String?\n  departmentId       String?\n  houseId            String?\n  previousSchool     String?\n  previousClass      String?\n  bloodGroup         String?\n  allergies          String?\n  medicalConditions  String?\n  outstandingBalance Decimal       @default(0) @db.Decimal(10, 2)\n  status             StudentStatus @default(ACTIVE)\n  plainTextPassword  String?\n  graduationDate     DateTime?     @db.Date\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  profile          UserProfile         @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school           School              @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  class            Class?              @relation(fields: [classId], references: [id])\n  department       Department?         @relation(fields: [departmentId], references: [id])\n  house            House?              @relation(fields: [houseId], references: [id])\n  assessmentScores AssessmentScore[]\n  attendances      Attendance[]\n  bills            Bill[]\n  documents        Document[]\n  enrollments      Enrollment[]\n  guardians        GuardianStudent[]\n  payments         Payment[]\n  remarks          Remark[]\n  transcripts      TranscriptRequest[]\n  reportCards      ReportCard[]\n  clubMembers      ClubMember[]\n  promotionRecords PromotionRecord[]\n\n  @@unique([studentId, schoolId])\n  @@unique([admissionNumber, schoolId])\n  @@index([schoolId, status])\n  @@index([classId, schoolId])\n  @@index([departmentId])\n  @@index([houseId])\n  @@index([profileId])\n  @@map(\"students\")\n}\n\nmodel Teacher {\n  id              String         @id @default(cuid())\n  profileId       String?        @unique\n  schoolId        String\n  teacherId       String\n  staffNumber     String?\n  invitationEmail String?\n  firstName       String? // For pending invitations\n  lastName        String? // For pending invitations\n  departmentId    String\n  houseId         String?\n  qualification   String?\n  specialization  String?\n  experience      Int?\n  employmentType  EmploymentType @default(FULL_TIME)\n  hireDate        DateTime       @default(now()) @db.Date\n  contractEndDate DateTime?      @db.Date\n  monthlySalary   Decimal?       @db.Decimal(10, 2)\n  isActive        Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  profile               UserProfile?     @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school                School           @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department            Department       @relation(\"TeacherDepartment\", fields: [departmentId], references: [id])\n  house                 House?           @relation(\"TeacherHouse\", fields: [houseId], references: [id])\n  classesAsClassTeacher Class[]\n  departmentsAsHead     Department[]     @relation(\"DepartmentHead\")\n  documents             Document[]\n  housesAsHouseTeacher  House[]          @relation(\"HouseTeacher\")\n  remarks               Remark[]\n  subjects              SubjectTeacher[]\n  classSubjects         ClassSubject[]\n  clubs                 Club[]\n  payslips              Payslip[]\n  timetableEntries      TimetableEntry[]\n\n  // Scoped to Academic Year\n  assignments          TeacherAssignment[]\n  assessmentExtensions AssessmentExtension[]\n\n  @@unique([teacherId, schoolId])\n  @@unique([staffNumber, schoolId])\n  @@index([schoolId, isActive])\n  @@index([departmentId])\n  @@index([houseId])\n  @@index([profileId])\n  @@index([invitationEmail])\n  @@map(\"teachers\")\n}\n\nmodel Staff {\n  id        String @id @default(cuid())\n  profileId String @unique\n  schoolId  String\n\n  // Staff Identifiers\n  staffId     String // Auto-generated school-specific ID\n  staffNumber String?\n\n  // Job Information\n  staffType    StaffType\n  departmentId String?\n  jobTitle     String?\n\n  // Employment Details\n  employmentType  EmploymentType @default(FULL_TIME)\n  hireDate        DateTime       @default(now()) @db.Date\n  contractEndDate DateTime?      @db.Date\n  monthlySalary   Decimal?       @db.Decimal(10, 2)\n  isActive        Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  profile    UserProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school     School      @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department Department? @relation(\"StaffDepartment\", fields: [departmentId], references: [id])\n  documents  Document[]\n  payslips   Payslip[]\n\n  // Scoped to Academic Year\n  assignments StaffAssignment[]\n\n  @@unique([staffId, schoolId])\n  @@unique([staffNumber, schoolId])\n  @@index([schoolId, isActive])\n  @@index([staffType])\n  @@index([profileId])\n  @@map(\"staff\")\n}\n\nmodel Guardian {\n  id                 String       @id @default(cuid())\n  profileId          String?\n  schoolId           String\n  guardianId         String\n  firstName          String\n  lastName           String\n  otherNames         String?\n  phone              String\n  alternatePhone     String?\n  email              String?\n  gender             Gender?\n  relationshipType   GuardianType\n  occupation         String?\n  employer           String?\n  workAddress        String?\n  workPhone          String?\n  residentialAddress String?\n  city               String?\n  region             String?\n  canLogin           Boolean      @default(false)\n  isActive           Boolean      @default(true)\n  createdAt          DateTime     @default(now())\n  updatedAt          DateTime     @updatedAt\n\n  profile  UserProfile?      @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school   School            @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  students GuardianStudent[]\n\n  @@unique([guardianId, schoolId])\n  @@index([schoolId, isActive])\n  @@index([profileId])\n  @@index([email])\n  @@index([canLogin])\n  @@map(\"guardians\")\n}\n\nmodel GuardianStudent {\n  id             String   @id @default(cuid())\n  guardianId     String\n  studentId      String\n  isPrimary      Boolean  @default(false)\n  canPickup      Boolean  @default(true)\n  receiveReports Boolean  @default(true)\n  receiveAlerts  Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  guardian Guardian @relation(fields: [guardianId], references: [id], onDelete: Cascade)\n  student  Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([guardianId, studentId])\n  @@index([guardianId])\n  @@index([studentId])\n  @@index([isPrimary])\n  @@map(\"guardian_students\")\n}\n\n// ============================================================================\n// ACADEMIC STRUCTURE\n// ============================================================================\n\nmodel House {\n  id             String   @id @default(cuid())\n  schoolId       String\n  name           String\n  code           String\n  description    String?\n  color          String?\n  motto          String?\n  houseTeacherId String?\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  school          School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  houseTeacher    Teacher?  @relation(\"HouseTeacher\", fields: [houseTeacherId], references: [id])\n  students        Student[]\n  teachersInHouse Teacher[] @relation(\"TeacherHouse\")\n\n  @@unique([code, schoolId])\n  @@index([houseTeacherId])\n  @@index([schoolId, isActive])\n  @@map(\"houses\")\n}\n\nmodel AcademicYear {\n  id        String   @id @default(cuid())\n  schoolId  String\n  name      String\n  startDate DateTime @db.Date\n  endDate   DateTime @db.Date\n  isCurrent Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school           School           @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  classes          Class[]\n  enrollments      Enrollment[]\n  terms            Term[]\n  reportCardSets   ReportCardSet[]\n  timetableEntries TimetableEntry[]\n\n  teacherAssignments    TeacherAssignment[]\n  staffAssignments      StaffAssignment[]\n  bills                 Bill[]                 @relation(\"AcademicYearBills\")\n  notifications         Notification[]\n  announcements         Announcement[]\n  expenses              Expense[]\n  inventoryTransactions InventoryTransaction[]\n  payrollRecords        PayrollRecord[]\n\n  @@unique([name, schoolId])\n  @@index([schoolId, isCurrent])\n  @@index([startDate, endDate])\n  @@map(\"academic_years\")\n}\n\nmodel Term {\n  id             String   @id @default(cuid())\n  academicYearId String\n  name           String\n  termNumber     Int\n  startDate      DateTime @db.Date\n  endDate        DateTime @db.Date\n  isCurrent      Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  academicYear          AcademicYear           @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  assessmentScores      AssessmentScore[]\n  bills                 Bill[]\n  enrollments           Enrollment[]\n  remarks               Remark[]\n  reportCardSets        ReportCardSet[]\n  notifications         Notification[]\n  announcements         Announcement[]\n  expenses              Expense[]\n  inventoryTransactions InventoryTransaction[]\n  payrollRecords        PayrollRecord[]\n\n  @@unique([academicYearId, termNumber])\n  @@index([academicYearId])\n  @@index([isCurrent])\n  @@index([startDate, endDate])\n  @@map(\"terms\")\n}\n\nmodel Department {\n  id                String   @id @default(cuid())\n  schoolId          String\n  name              String\n  code              String\n  description       String?\n  headOfDeptId      String?\n  promotionPassMark Decimal? @db.Decimal(5, 2)\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  school               School               @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  headOfDept           Teacher?             @relation(\"DepartmentHead\", fields: [headOfDeptId], references: [id])\n  students             Student[]\n  subjects             Subject[]            @relation(\"DepartmentSubjects\")\n  teachersInDepartment Teacher[]            @relation(\"TeacherDepartment\")\n  staff                Staff[]              @relation(\"StaffDepartment\")\n  classes              Class[]\n  timetableEntries     TimetableEntry[]\n  assessmentTemplates  AssessmentTemplate[]\n  reportCardTemplates  ReportCardTemplate[]\n  periodTemplates      PeriodTemplate[]     @relation(\"DeptPeriodTemplates\")\n  timeSlots            TimeSlot[]           @relation(\"DeptTimeSlots\")\n\n  @@unique([code, schoolId])\n  @@index([headOfDeptId])\n  @@index([schoolId, isActive])\n  @@map(\"departments\")\n}\n\nmodel Class {\n  id             String @id @default(cuid())\n  schoolId       String\n  academicYearId String\n\n  name     String\n  slug     String?\n  level    String\n  capacity Int?\n\n  classTeacherId String?\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  school                    School                    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  academicYear              AcademicYear              @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  classTeacher              Teacher?                  @relation(fields: [classTeacherId], references: [id])\n  subjects                  ClassSubject[]\n  enrollments               Enrollment[]\n  students                  Student[]\n  departmentId              String?\n  department                Department?               @relation(fields: [departmentId], references: [id])\n  assessmentTemplates       AssessmentTemplate[]\n  assessmentTemplateClasses AssessmentTemplateClass[]\n  reportCardSets            ReportCardSet[]\n  reportCardSetClasses      ReportCardSetClass[]\n  assessmentExtensions      AssessmentExtension[]\n  timetableEntries          TimetableEntry[]\n\n  feeStructures FeeStructureClass[]\n\n  nextPromotionClassId String?\n  nextPromotionClass   Class?  @relation(\"ClassPromotion\", fields: [nextPromotionClassId], references: [id])\n  prevPromotionClasses Class[] @relation(\"ClassPromotion\")\n\n  isGraduatingClass Boolean @default(false) // Last class in the school (e.g. JHS 3)\n  order             Int? // Hierarchy order for sorting (1=lowest, n=highest)\n\n  bills         Bill[]\n  promotionsSrc PromotionRecord[] @relation(\"PromotionFrom\")\n  promotionsDst PromotionRecord[] @relation(\"PromotionTo\")\n\n  @@unique([name, academicYearId, schoolId])\n  @@unique([slug, academicYearId, schoolId])\n  @@index([schoolId, isActive])\n  @@index([academicYearId])\n  @@index([classTeacherId])\n  @@map(\"classes\")\n}\n\nmodel TeacherAssignment {\n  id             String   @id @default(cuid())\n  schoolId       String\n  teacherId      String\n  academicYearId String\n  createdAt      DateTime @default(now())\n\n  school       School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  teacher      Teacher      @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n\n  @@unique([teacherId, academicYearId, schoolId])\n  @@map(\"teacher_assignments\")\n}\n\nmodel StaffAssignment {\n  id             String   @id @default(cuid())\n  schoolId       String\n  staffId        String\n  academicYearId String\n  createdAt      DateTime @default(now())\n\n  school       School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  staff        Staff        @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n\n  @@unique([staffId, academicYearId, schoolId])\n  @@map(\"staff_assignments\")\n}\n\nmodel Subject {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  creditHours Int      @default(1)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school           School            @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  departments      Department[]      @relation(\"DepartmentSubjects\")\n  assessmentScores AssessmentScore[]\n  classSubjects    ClassSubject[]\n  teachers         SubjectTeacher[]\n  timetableEntries TimetableEntry[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@map(\"subjects\")\n}\n\nmodel ClassSubject {\n  id           String   @id @default(cuid())\n  classId      String\n  subjectId    String\n  isCompulsory Boolean  @default(true)\n  teacherId    String?\n  createdAt    DateTime @default(now())\n\n  class   Class    @relation(fields: [classId], references: [id], onDelete: Cascade)\n  subject Subject  @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  teacher Teacher? @relation(fields: [teacherId], references: [id])\n\n  @@unique([classId, subjectId])\n  @@index([classId])\n  @@index([subjectId])\n  @@index([teacherId])\n  @@map(\"class_subjects\")\n}\n\nmodel SubjectTeacher {\n  id        String @id @default(cuid())\n  subjectId String\n  teacherId String\n\n  createdAt DateTime @default(now())\n\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  teacher Teacher @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n\n  @@unique([subjectId, teacherId])\n  @@index([subjectId])\n  @@index([teacherId])\n  @@map(\"subject_teachers\")\n}\n\nmodel Enrollment {\n  id             String           @id @default(cuid())\n  studentId      String\n  classId        String\n  academicYearId String\n  termId         String\n  status         EnrollmentStatus @default(ACTIVE)\n  enrolledAt     DateTime         @default(now())\n  completedAt    DateTime?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  student      Student      @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  class        Class        @relation(fields: [classId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  term         Term         @relation(fields: [termId], references: [id])\n\n  @@unique([studentId, classId, academicYearId, termId])\n  @@index([studentId])\n  @@index([classId, academicYearId, status])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"enrollments\")\n}\n\n// ============================================================================\n// ATTENDANCE & ASSESSMENT\n// ============================================================================\n\nmodel Attendance {\n  id        String @id @default(cuid())\n  studentId String\n\n  date    DateTime         @db.Date\n  status  AttendanceStatus\n  remarks String?\n\n  markedById String?\n  markedAt   DateTime @default(now())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  student  Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  markedBy user?   @relation(\"AttendanceMarkedBy\", fields: [markedById], references: [id], onDelete: SetNull)\n\n  @@unique([studentId, date])\n  @@index([studentId])\n  @@index([date, status])\n  @@index([markedById])\n  @@map(\"attendances\")\n}\n\nmodel GradingSystem {\n  id              String   @id @default(cuid())\n  schoolId        String?\n  name            String\n  code            String\n  description     String?\n  isSystemDefault Boolean  @default(false)\n  isSchoolDefault Boolean  @default(false)\n  isActive        Boolean  @default(true)\n  createdById     String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  school              School?              @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  createdBy           user?                @relation(fields: [createdById], references: [id], onDelete: SetNull)\n  assessmentTemplates AssessmentTemplate[]\n  gradeScales         GradeScale[]\n\n  @@unique([code, schoolId])\n  @@index([createdById])\n  @@index([schoolId, isActive])\n  @@index([isSystemDefault])\n  @@index([isSchoolDefault])\n  @@map(\"grading_systems\")\n}\n\nmodel GradeScale {\n  id              String   @id @default(cuid())\n  gradingSystemId String\n  grade           String\n  description     String\n  minScore        Decimal  @db.Decimal(5, 2)\n  maxScore        Decimal  @db.Decimal(5, 2)\n  gradePoint      Decimal  @db.Decimal(3, 2)\n  displayOrder    Int\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  gradingSystem GradingSystem @relation(fields: [gradingSystemId], references: [id], onDelete: Cascade)\n\n  @@unique([gradingSystemId, grade])\n  @@index([gradingSystemId])\n  @@index([minScore, maxScore])\n  @@map(\"grade_scales\")\n}\n\nmodel AssessmentTemplate {\n  id              String    @id @default(cuid())\n  schoolId        String\n  gradingSystemId String\n  name            String\n  description     String?\n  termNumber      Int?\n  isActive        Boolean   @default(true)\n  deadline        DateTime?\n  isLocked        Boolean   @default(false)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  school           School                    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  gradingSystem    GradingSystem             @relation(fields: [gradingSystemId], references: [id])\n  classId          String?\n  classLevel       String?\n  subjectCode      String?\n  class            Class?                    @relation(fields: [classId], references: [id])\n  departmentId     String?\n  department       Department?               @relation(fields: [departmentId], references: [id])\n  classes          AssessmentTemplateClass[]\n  components       AssessmentComponent[]\n  assessmentScores AssessmentScore[]\n  extensions       AssessmentExtension[]\n\n  @@index([schoolId, isActive])\n  @@index([gradingSystemId])\n  @@map(\"assessment_templates\")\n}\n\nmodel AssessmentComponent {\n  id            String         @id @default(cuid())\n  templateId    String\n  name          String\n  componentType AssessmentType\n  maxMarks      Decimal        @db.Decimal(6, 2)\n  weight        Decimal        @db.Decimal(5, 2)\n  displayOrder  Int\n  isRequired    Boolean        @default(true)\n  // Repeatable components (e.g. Class Tests) allow multiple entries;\n  // the average of all entries is used as the effective score for weighting.\n  isRepeatable  Boolean        @default(false)\n  expectedCount Int            @default(1) // how many occurrences are expected\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n\n  template AssessmentTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  scores   ComponentScore[]\n\n  @@index([templateId])\n  @@index([componentType])\n  @@map(\"assessment_components\")\n}\n\nmodel AssessmentScore {\n  id         String                @id @default(cuid())\n  studentId  String\n  subjectId  String\n  termId     String\n  templateId String\n  totalScore Decimal               @db.Decimal(6, 2)\n  percentage Decimal               @db.Decimal(5, 2)\n  status     AssessmentScoreStatus @default(DRAFT)\n  isLocked   Boolean               @default(false)\n  grade      String?\n  gradePoint Decimal?              @db.Decimal(3, 2)\n  position   Int?\n  remarks    String?\n  createdAt  DateTime              @default(now())\n  updatedAt  DateTime              @updatedAt\n\n  student         Student            @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  subject         Subject            @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  term            Term               @relation(fields: [termId], references: [id], onDelete: Cascade)\n  template        AssessmentTemplate @relation(fields: [templateId], references: [id])\n  componentScores ComponentScore[]\n\n  @@unique([studentId, subjectId, termId, templateId])\n  @@index([studentId, termId])\n  @@index([subjectId, termId])\n  @@index([templateId])\n  @@map(\"assessment_scores\")\n}\n\nmodel ComponentScore {\n  id                String   @id @default(cuid())\n  assessmentScoreId String\n  componentId       String\n  occurrenceIndex   Int      @default(0) // 0 = single/first, 1 = second, etc. for repeatable components\n  marksObtained     Decimal  @db.Decimal(6, 2)\n  maxMarks          Decimal  @db.Decimal(6, 2)\n  percentage        Decimal  @db.Decimal(5, 2)\n  weightedScore     Decimal  @db.Decimal(6, 2)\n  rawScores         Json?\n  recordedById      String?\n  recordedAt        DateTime @default(now())\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  assessmentScore AssessmentScore     @relation(fields: [assessmentScoreId], references: [id], onDelete: Cascade)\n  component       AssessmentComponent @relation(fields: [componentId], references: [id])\n  recordedBy      user?               @relation(fields: [recordedById], references: [id], onDelete: SetNull)\n\n  @@unique([assessmentScoreId, componentId, occurrenceIndex])\n  @@index([assessmentScoreId])\n  @@index([componentId])\n  @@index([recordedById])\n  @@map(\"component_scores\")\n}\n\nmodel Remark {\n  id         String     @id @default(cuid())\n  studentId  String\n  teacherId  String\n  termId     String\n  remarkType RemarkType\n  content    String\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  term    Term    @relation(fields: [termId], references: [id], onDelete: Cascade)\n\n  @@index([studentId, termId])\n  @@index([teacherId])\n  @@index([remarkType])\n  @@map(\"remarks\")\n}\n\nmodel TranscriptRequest {\n  id          String                @id @default(cuid())\n  studentId   String\n  requestType TranscriptRequestType\n  purpose     String?\n  status      RequestStatus         @default(PENDING)\n\n  requestedAt   DateTime  @default(now())\n  processedAt   DateTime?\n  processedById String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  student     Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  processedBy user?   @relation(fields: [processedById], references: [id], onDelete: SetNull)\n\n  @@index([studentId])\n  @@index([status])\n  @@index([requestedAt])\n  @@index([processedById])\n  @@map(\"transcript_requests\")\n}\n\n// ============================================================================\n// REPORT CARDS & NOTIFICATIONS\n// ============================================================================\n\nmodel ReportCardTemplate {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  description String?\n  layout      Json // For storing configuration of sections, titles, etc.\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Level scoping: references the school department that represents this level\n  // e.g. \"Primary\" department → primary-level template with SEL rubrics\n  departmentId String?\n\n  // Level-specific configuration payloads (stored as JSON for flexibility)\n  developmentalConfig Json? // Creche/KG: milestone categories & tracking items\n  selConfig           Json? // Primary: Social-Emotional Learning rubric definitions\n  disciplineConfig    Json? // JHS: discipline, readiness, and predictive rubrics\n\n  school     School          @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department Department?     @relation(fields: [departmentId], references: [id])\n  sets       ReportCardSet[]\n\n  @@index([schoolId])\n  @@index([departmentId])\n  @@map(\"report_card_templates\")\n}\n\nmodel ReportCardSet {\n  id             String               @id @default(cuid())\n  schoolId       String\n  templateId     String\n  academicYearId String\n  termId         String\n  classId        String? // Keep for single-class backward compatibility or primary class\n  name           String // e.g. \"Primary 1 - Term 1 - 2025\"\n  status         ReportCardStatus     @default(DRAFT)\n  targetClasses  ReportCardSetClass[]\n  publishAt      DateTime?\n  publishedAt    DateTime?\n  createdAt      DateTime             @default(now())\n  updatedAt      DateTime             @updatedAt\n\n  school       School             @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  template     ReportCardTemplate @relation(fields: [templateId], references: [id])\n  academicYear AcademicYear       @relation(fields: [academicYearId], references: [id])\n  term         Term               @relation(fields: [termId], references: [id])\n  class        Class?             @relation(fields: [classId], references: [id])\n  reportCards  ReportCard[]\n\n  @@index([schoolId])\n  @@index([academicYearId])\n  @@index([termId])\n  @@index([classId])\n  @@map(\"report_card_sets\")\n}\n\nmodel ReportCard {\n  id          String    @id @default(cuid())\n  setId       String\n  studentId   String\n  data        Json // Snapshot of all required data: subjects, marks, positions, attendance, remarks\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  set               ReportCardSet      @relation(fields: [setId], references: [id], onDelete: Cascade)\n  student           Student            @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  behavioralRemarks BehavioralRemark[]\n\n  @@unique([setId, studentId])\n  @@index([setId])\n  @@index([studentId])\n  @@map(\"report_cards\")\n}\n\n// Hybrid Remark System: structured behavioral pillar entries per report card\nmodel BehavioralRemark {\n  id           String           @id @default(cuid())\n  reportCardId String\n  pillar       BehavioralPillar\n  // Predefined value (e.g. \"Excellent\", \"Satisfactory\") or custom text when pillar = OTHER\n  value        String\n  createdAt    DateTime         @default(now())\n  updatedAt    DateTime         @updatedAt\n\n  reportCard ReportCard @relation(fields: [reportCardId], references: [id], onDelete: Cascade)\n\n  @@index([reportCardId])\n  @@map(\"behavioral_remarks\")\n}\n\nmodel Notification {\n  id        String           @id @default(cuid())\n  schoolId  String\n  userId    String // Recipient\n  type      NotificationType\n  title     String\n  message   String\n  isRead    Boolean          @default(false)\n  link      String? // Redirect link\n  createdAt DateTime         @default(now())\n  updatedAt DateTime         @updatedAt\n\n  academicYearId String?\n  termId         String?\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  user         user          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear? @relation(fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n\n  @@index([schoolId])\n  @@index([userId])\n  @@index([type])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"notifications\")\n}\n\nmodel Announcement {\n  id        String    @id @default(cuid())\n  schoolId  String\n  authorId  String\n  title     String\n  content   String\n  target    String    @default(\"ALL\") // ALL, TEACHER, STUDENT, STAFF\n  expiresAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  academicYearId String?\n  termId         String?\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  author       user          @relation(\"AnnouncementsSent\", fields: [authorId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear? @relation(fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n\n  @@index([schoolId])\n  @@index([authorId])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"announcements\")\n}\n\n// ============================================================================\n// FINANCE & ACCOUNTING\n// Complex models for audit trail purposes\n// ============================================================================\n\nmodel ChartAccount {\n  id          String          @id @default(cuid())\n  schoolId    String\n  code        String\n  name        String\n  description String?\n  accountType AccountType\n  category    AccountCategory\n  parentId    String?\n  balance     Decimal         @default(0) @db.Decimal(15, 2)\n  isActive    Boolean         @default(true)\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  school             School         @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  parent             ChartAccount?  @relation(\"AccountHierarchy\", fields: [parentId], references: [id])\n  children           ChartAccount[] @relation(\"AccountHierarchy\")\n  creditTransactions Transaction[]  @relation(\"CreditAccount\")\n  debitTransactions  Transaction[]  @relation(\"DebitAccount\")\n\n  @@unique([code, schoolId])\n  @@index([schoolId, accountType])\n  @@index([category])\n  @@index([parentId])\n  @@index([isActive])\n  @@map(\"chart_accounts\")\n}\n\nmodel FeeStructure {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  description String?\n  classLevel  String?\n  termBased   Boolean  @default(true)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  bills  Bill[]\n  items  FeeItem[]\n\n  // Support for multi-select classes\n  targetClasses FeeStructureClass[]\n\n  @@index([schoolId, isActive])\n  @@map(\"fee_structures\")\n}\n\nmodel FeeStructureClass {\n  id             String @id @default(cuid())\n  feeStructureId String\n  classId        String\n\n  feeStructure FeeStructure @relation(fields: [feeStructureId], references: [id], onDelete: Cascade)\n  class        Class        @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  @@unique([feeStructureId, classId])\n  @@map(\"fee_structure_classes\")\n}\n\nmodel FeeItemRegistry {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school   School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  feeItems FeeItem[]\n\n  @@unique([name, schoolId])\n  @@map(\"fee_item_registry\")\n}\n\nmodel FeeItem {\n  id               String       @id @default(cuid())\n  feeStructureId   String\n  name             String\n  description      String?\n  amount           Decimal      @db.Decimal(10, 2)\n  category         FeeCategory?\n  customCategoryId String?\n  isOptional       Boolean      @default(false)\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  feeStructure   FeeStructure       @relation(fields: [feeStructureId], references: [id], onDelete: Cascade)\n  customCategory CustomFeeCategory? @relation(fields: [customCategoryId], references: [id])\n  billItems      BillItem[]\n\n  registryItemId String?\n  registryItem   FeeItemRegistry? @relation(fields: [registryItemId], references: [id])\n\n  @@index([feeStructureId])\n  @@index([category])\n  @@index([customCategoryId])\n  @@map(\"fee_items\")\n}\n\nmodel Bill {\n  id             String     @id @default(cuid())\n  schoolId       String\n  studentId      String\n  academicYearId String\n  termId         String?\n  feeStructureId String?\n  billNumber     String\n  billCode       String?\n  totalAmount    Decimal    @db.Decimal(10, 2)\n  paidAmount     Decimal    @default(0) @db.Decimal(10, 2)\n  balanceAmount  Decimal    @db.Decimal(10, 2)\n  status         BillStatus @default(PENDING)\n  dueDate        DateTime?  @db.Date\n  issuedAt       DateTime   @default(now())\n  notes          String?\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student      Student       @relation(fields: [studentId], references: [id])\n  academicYear AcademicYear  @relation(\"AcademicYearBills\", fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n  feeStructure FeeStructure? @relation(fields: [feeStructureId], references: [id])\n  class        Class?        @relation(fields: [classId], references: [id])\n  items        BillItem[]\n  payments     Payment[]\n\n  classId  String?\n  billType BillType @default(INVOICE)\n\n  @@unique([billNumber, schoolId])\n  @@unique([billCode, schoolId])\n  @@index([schoolId, status])\n  @@index([studentId, academicYearId, status])\n  @@index([billNumber])\n  @@index([billCode])\n  @@index([dueDate])\n  @@index([academicYearId])\n  @@index([termId])\n  @@index([feeStructureId])\n  @@index([classId])\n  @@index([billType])\n  @@map(\"bills\")\n}\n\nmodel BillItem {\n  id        String  @id @default(cuid())\n  billId    String\n  feeItemId String?\n\n  description String\n  amount      Decimal  @db.Decimal(10, 2)\n  quantity    Int      @default(1)\n  totalAmount Decimal  @db.Decimal(10, 2)\n  createdAt   DateTime @default(now())\n\n  bill    Bill     @relation(fields: [billId], references: [id], onDelete: Cascade)\n  feeItem FeeItem? @relation(fields: [feeItemId], references: [id])\n\n  paidAmount    Decimal        @default(0) @db.Decimal(10, 2)\n  balanceAmount Decimal        @db.Decimal(10, 2)\n  status        BillItemStatus @default(UNPAID)\n\n  paymentItems PaymentItem[]\n\n  @@index([billId])\n  @@index([feeItemId])\n  @@map(\"bill_items\")\n}\n\nenum BillItemStatus {\n  UNPAID\n  PARTIALLY_PAID\n  FULLY_PAID\n}\n\nmodel Payment {\n  id        String  @id @default(cuid())\n  schoolId  String\n  studentId String\n  billId    String?\n\n  paymentNumber   String\n  amount          Decimal       @db.Decimal(10, 2)\n  paymentMethod   PaymentMethod\n  paymentDate     DateTime      @db.Date\n  referenceNumber String?\n  transactionId   String?\n  status          PaymentStatus @default(COMPLETED)\n  notes           String?\n  recordedById    String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  school      School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student     Student      @relation(fields: [studentId], references: [id])\n  bill        Bill?        @relation(fields: [billId], references: [id])\n  transaction Transaction? @relation(fields: [transactionId], references: [id])\n  recordedBy  user?        @relation(\"PaymentRecordedBy\", fields: [recordedById], references: [id], onDelete: SetNull)\n\n  paymentItems PaymentItem[]\n\n  @@unique([paymentNumber, schoolId])\n  @@index([schoolId, paymentDate])\n  @@index([studentId])\n  @@index([billId])\n  @@index([paymentNumber])\n  @@index([status])\n  @@index([transactionId])\n  @@index([recordedById])\n  @@map(\"payments\")\n}\n\nmodel PaymentItem {\n  id         String   @id @default(cuid())\n  paymentId  String\n  billItemId String\n  amount     Decimal  @db.Decimal(10, 2)\n  createdAt  DateTime @default(now())\n\n  payment  Payment  @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  billItem BillItem @relation(fields: [billItemId], references: [id], onDelete: Cascade)\n\n  @@index([paymentId])\n  @@index([billItemId])\n  @@map(\"payment_items\")\n}\n\nmodel Transaction {\n  id                String               @id @default(cuid())\n  schoolId          String\n  transactionNumber String\n  transactionDate   DateTime             @db.Date\n  description       String\n  amount            Decimal              @db.Decimal(15, 2)\n  debitAccountId    String\n  creditAccountId   String\n  transactionType   TransactionType\n  category          TransactionCategory?\n  customCategoryId  String?\n  referenceType     String?\n  referenceId       String?\n  referenceNumber   String?\n  notes             String?\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @updatedAt\n\n  school         School                     @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  debitAccount   ChartAccount               @relation(\"DebitAccount\", fields: [debitAccountId], references: [id])\n  creditAccount  ChartAccount               @relation(\"CreditAccount\", fields: [creditAccountId], references: [id])\n  customCategory CustomTransactionCategory? @relation(fields: [customCategoryId], references: [id])\n  payments       Payment[]\n\n  @@unique([transactionNumber, schoolId])\n  @@index([schoolId, transactionDate])\n  @@index([schoolId, transactionType])\n  @@index([transactionNumber])\n  @@index([debitAccountId])\n  @@index([creditAccountId])\n  @@index([category])\n  @@index([customCategoryId])\n  @@map(\"transactions\")\n}\n\n// ============================================================================\n// PROMOTION RECORDS\n// ============================================================================\n\nmodel PromotionRecord {\n  id            String        @id @default(cuid())\n  schoolId      String\n  studentId     String\n  fromClassId   String\n  toClassId     String?\n  fromYearId    String\n  toYearId      String?\n  promotionType PromotionType\n  promotedById  String\n  promotedAt    DateTime      @default(now())\n  notes         String?\n  reason        String?\n\n  school     School  @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student    Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  fromClass  Class   @relation(\"PromotionFrom\", fields: [fromClassId], references: [id])\n  toClass    Class?  @relation(\"PromotionTo\", fields: [toClassId], references: [id])\n  promotedBy user    @relation(\"PromotedBy\", fields: [promotedById], references: [id])\n\n  @@index([schoolId])\n  @@index([studentId])\n  @@index([fromClassId])\n  @@index([toClassId])\n  @@index([fromYearId])\n  @@index([toYearId])\n  @@index([promotionType])\n  @@map(\"promotion_records\")\n}\n\nenum PromotionType {\n  PROMOTED // Normal promotion to next class\n  REPEATED // Student repeats the same class\n  GRADUATED // Student completed the final class\n  SKIPPED // Special/accelerated — skipped one or more classes\n}\n\nenum BehavioralPillar {\n  PUNCTUALITY\n  CONDUCT\n  ATTITUDE\n  OTHER\n}\n\n// Custom Categories for Financial Flexibility\nmodel CustomFeeCategory {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school   School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  feeItems FeeItem[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@map(\"custom_fee_categories\")\n}\n\nmodel CustomExpenseCategory {\n  id       String @id @default(cuid())\n  schoolId String\n\n  name        String\n  code        String\n  description String?\n  accountType AccountType\n  isActive    Boolean     @default(true)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  school School @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([accountType])\n  @@map(\"custom_expense_categories\")\n}\n\nmodel CustomTransactionCategory {\n  id       String @id @default(cuid())\n  schoolId String\n\n  name         String\n  code         String\n  description  String?\n  categoryType TransactionType\n  isActive     Boolean         @default(true)\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  transactions Transaction[]\n  expenses     Expense[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([categoryType])\n  @@map(\"custom_transaction_categories\")\n}\n\nmodel Expense {\n  id               String               @id @default(cuid())\n  schoolId         String\n  date             DateTime             @db.Date\n  amount           Decimal              @db.Decimal(15, 2)\n  category         TransactionCategory?\n  customCategoryId String?\n  description      String\n  payee            String?\n  paymentMethod    PaymentMethod        @default(CASH)\n  checkNumber      String?\n  voucherNumber    String? // POV\n  referenceNumber  String?\n  recordedById     String?\n  createdAt        DateTime             @default(now())\n  updatedAt        DateTime             @updatedAt\n\n  academicYearId String?\n  termId         String?\n\n  school         School                     @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  customCategory CustomTransactionCategory? @relation(fields: [customCategoryId], references: [id])\n  recordedBy     user?                      @relation(\"ExpenseRecordedBy\", fields: [recordedById], references: [id], onDelete: SetNull)\n  academicYear   AcademicYear?              @relation(fields: [academicYearId], references: [id])\n  term           Term?                      @relation(fields: [termId], references: [id])\n\n  registryCategoryId String?\n  registryCategory   ExpenditureCategoryRegistry? @relation(fields: [registryCategoryId], references: [id])\n\n  @@index([schoolId, date])\n  @@index([category])\n  @@index([recordedById])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"expenses\")\n}\n\nmodel ExpenditureCategoryRegistry {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school   School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  expenses Expense[]\n\n  @@unique([name, schoolId])\n  @@map(\"expenditure_category_registry\")\n}\n\nmodel InventoryItem {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  description String?\n  category    String?\n  quantity    Int      @default(0)\n  unit        String?  @default(\"pcs\")\n  minQuantity Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school       School                 @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  transactions InventoryTransaction[]\n\n  @@unique([name, schoolId])\n  @@index([schoolId])\n  @@map(\"inventory_items\")\n}\n\nmodel InventoryTransaction {\n  id            String                   @id @default(cuid())\n  schoolId      String\n  itemId        String\n  type          InventoryTransactionType\n  quantity      Int\n  date          DateTime                 @default(now())\n  description   String?\n  performedById String?\n  createdAt     DateTime                 @default(now())\n\n  // Stock Issuance tracking\n  recipientName String?\n  recipientId   String?\n\n  academicYearId String?\n  termId         String?\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  item         InventoryItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  performedBy  user?         @relation(\"InventoryPerformedBy\", fields: [performedById], references: [id], onDelete: SetNull)\n  academicYear AcademicYear? @relation(fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n  recipient    user?         @relation(\"InventoryRecipient\", fields: [recipientId], references: [id], onDelete: SetNull)\n\n  @@index([itemId])\n  @@index([schoolId])\n  @@index([academicYearId])\n  @@index([termId])\n  @@index([recipientId])\n  @@map(\"inventory_transactions\")\n}\n\nenum InventoryTransactionType {\n  IN\n  OUT\n  ADJUSTMENT\n}\n\n// ============================================================================\n// DOCUMENTS & AUDIT\n// ============================================================================\n\nmodel Document {\n  id           String     @id @default(cuid())\n  schoolId     String\n  title        String\n  description  String?\n  fileUrl      String\n  fileType     String\n  fileSize     Int\n  entityType   EntityType\n  entityId     String\n  studentId    String?\n  teacherId    String?\n  staffId      String?\n  uploadedById String?\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  school     School   @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student    Student? @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  teacher    Teacher? @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n  staff      Staff?   @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  uploadedBy user?    @relation(fields: [uploadedById], references: [id], onDelete: SetNull)\n\n  @@index([uploadedById])\n  @@index([schoolId])\n  @@index([entityType, entityId])\n  @@index([studentId])\n  @@index([teacherId])\n  @@index([staffId])\n  @@map(\"documents\")\n}\n\nmodel AuditLog {\n  id       String  @id @default(cuid())\n  userId   String\n  schoolId String?\n\n  action     AuditAction\n  entityType String\n  entityId   String\n  oldValues  Json?\n  newValues  Json?\n  ipAddress  String?\n  userAgent  String?\n  createdAt  DateTime    @default(now())\n\n  user   user    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  school School? @relation(fields: [schoolId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([schoolId])\n  @@index([entityType, entityId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ============================================================================\n// SUBSCRIPTION & BILLING\n// ============================================================================\n\nmodel Subscription {\n  id       String @id @default(cuid())\n  schoolId String @unique\n\n  planType     PlanType           @default(FREE)\n  planName     String             @default(\"Free Plan\")\n  billingCycle BillingCycle?\n  status       SubscriptionStatus @default(ACTIVE)\n\n  amount   Decimal? @db.Decimal(10, 2)\n  currency String   @default(\"USD\")\n\n  // Trial Period\n  trialStartsAt DateTime?\n  trialEndsAt   DateTime?\n  isOnTrial     Boolean   @default(false)\n\n  // Billing Period\n  currentPeriodStart DateTime?\n  currentPeriodEnd   DateTime?\n\n  // Stripe Integration\n  stripeCustomerId      String? @unique\n  stripeSubscriptionId  String? @unique\n  stripePaymentMethodId String?\n\n  // Paystack Integration\n  paystackEmail            String?\n  paystackCustomerCode     String?\n  paystackSubscriptionCode String?\n  paystackTransactionId    String?\n\n  // Cancellation\n  cancelAtPeriodEnd Boolean   @default(false)\n  canceledAt        DateTime?\n\n  // Plan Limits\n  maxStudents Int?\n  maxTeachers Int?\n  maxStaff    Int?\n\n  // Flexible settings\n  settings Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school   School          @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  invoices InvoiceRecord[]\n\n  @@index([schoolId])\n  @@index([status])\n  @@index([planType])\n  @@index([stripeCustomerId])\n  @@index([stripeSubscriptionId])\n  @@map(\"subscriptions\")\n}\n\nmodel InvoiceRecord {\n  id             String @id @default(cuid())\n  subscriptionId String\n\n  invoiceNumber String        @unique\n  amount        Decimal       @db.Decimal(10, 2)\n  currency      String        @default(\"USD\")\n  status        InvoiceStatus @default(PENDING)\n\n  periodStart DateTime\n  periodEnd   DateTime\n  paidAt      DateTime?\n\n  paymentMethod String?\n\n  // Stripe Integration\n  stripeInvoiceId String?  @unique\n  invoiceUrl      String?\n  pdfUrl          String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  subscription Subscription @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)\n\n  @@index([subscriptionId])\n  @@index([status])\n  @@index([invoiceNumber])\n  @@map(\"invoice_records\")\n}\n\n// ============================================================\n// ENUMS\n// ============================================================\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum GuardianType {\n  FATHER\n  MOTHER\n  GUARDIAN\n  SIBLING\n  RELATIVE\n  OTHER\n}\n\nenum StaffType {\n  ACCOUNTANT\n  ADMIN\n  LIBRARIAN\n  DRIVER\n  SECURITY\n  NURSE\n  COUNSELOR\n  IT_SUPPORT\n  RECEPTIONIST\n  COOK\n  CLEANER\n  OTHER\n}\n\nenum EmploymentType {\n  FULL_TIME\n  PART_TIME\n  CONTRACT\n  TEMPORARY\n  INTERN\n}\n\nenum StudentStatus {\n  ACTIVE\n  GRADUATED\n  WITHDRAWN\n  SUSPENDED\n  TRANSFERRED\n  EXPELLED\n  DECEASED\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n  SICK\n  PERMISSION\n}\n\nenum EnrollmentStatus {\n  ACTIVE\n  COMPLETED\n  WITHDRAWN\n  TRANSFERRED\n  SUSPENDED\n}\n\nenum AssessmentType {\n  FINAL_EXAM\n  MID_TERM_EXAM\n  CLASS_TEST\n  QUIZ\n  ASSIGNMENT\n  PROJECT\n  PRACTICAL\n  HOMEWORK\n  PRESENTATION\n  MOCK_EXAM\n}\n\nenum RequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSING\n  COMPLETED\n  CANCELLED\n}\n\nenum RemarkType {\n  ACADEMIC\n  BEHAVIORAL\n  ATTENDANCE\n  GENERAL\n  ACHIEVEMENT\n  CONCERN\n}\n\nenum AccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  REVENUE\n  EXPENSE\n}\n\nenum AccountCategory {\n  CASH\n  BANK\n  ACCOUNTS_RECEIVABLE\n  FIXED_ASSETS\n  INVENTORY\n  PREPAID_EXPENSES\n  ACCOUNTS_PAYABLE\n  ACCRUED_EXPENSES\n  LONG_TERM_DEBT\n  EQUITY_CAPITAL\n  RETAINED_EARNINGS\n  SCHOOL_FEES\n  OTHER_INCOME\n  SALARY_WAGES\n  UTILITIES\n  RENT\n  SUPPLIES\n  MAINTENANCE\n  TRANSPORT\n  INSURANCE\n  TAXES\n  OTHER_EXPENSE\n}\n\nenum FeeCategory {\n  TUITION\n  ADMISSION\n  REGISTRATION\n  EXAM\n  LIBRARY\n  LABORATORY\n  SPORTS\n  TRANSPORT\n  MEAL\n  UNIFORM\n  BOOKS\n  TECHNOLOGY\n  HOSTEL\n  INSURANCE\n  DEVELOPMENT\n  OTHER\n}\n\nenum BillStatus {\n  PENDING\n  PARTIALLY_PAID\n  PAID\n  OVERDUE\n  WAIVED\n  CANCELLED\n}\n\nenum BillType {\n  PROFORMA // Estimate issued before class placement is confirmed\n  INVOICE // Final bill after student is enrolled/promoted\n}\n\nenum PaymentMethod {\n  CASH\n  BANK_TRANSFER\n  CHEQUE\n  MOBILE_MONEY\n  CARD\n  ONLINE\n  OTHER\n}\n\nenum PaymentStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REFUNDED\n  CANCELLED\n}\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n  TRANSFER\n  ADJUSTMENT\n}\n\nenum TransactionCategory {\n  SCHOOL_FEES\n  SALARY\n  UTILITIES\n  SUPPLIES\n  MAINTENANCE\n  TRANSPORT\n  RENT\n  INSURANCE\n  TAXES\n  DONATION\n  GRANT\n  OTHER\n}\n\nenum TranscriptRequestType {\n  OFFICIAL\n  UNOFFICIAL\n  BECE_TRANSCRIPT\n  WASSCE_TRANSCRIPT\n  TRANSFER_CERTIFICATE\n  PROGRESS_REPORT\n  FINAL_TRANSCRIPT\n  OTHER\n}\n\nenum AuditAction {\n  CREATE\n  UPDATE\n  DELETE\n  LOGIN\n  LOGOUT\n  PAYMENT_RECORDED\n  BILL_GENERATED\n  GRADE_ENTERED\n  ATTENDANCE_MARKED\n}\n\nenum PlanType {\n  FREE\n  BASIC\n  STANDARD\n  PREMIUM\n  ENTERPRISE\n}\n\nenum BillingCycle {\n  MONTHLY\n  YEARLY\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  TRIALING\n  PAST_DUE\n  CANCELED\n  INCOMPLETE\n  INCOMPLETE_EXPIRED\n  UNPAID\n  EXPIRED\n  SUSPENDED\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n  VOID\n}\n\nenum EntityType {\n  STUDENT\n  TEACHER\n  STAFF\n  SCHOOL\n  BILL\n  PAYMENT\n  OTHER\n}\n\nenum ReportCardStatus {\n  DRAFT\n  GENERATING\n  GENERATED\n  PUBLISHED\n  ARCHIVED\n}\n\nenum NotificationType {\n  RESULT_PUBLISHED\n  FEE_REMINDER\n  ATTENDANCE_ALERT\n  GENERAL\n  ANNOUNCEMENT\n  ONLINE_PAYMENT\n}\n\n// ============================================================================\n// SUPPORT / TICKETING\n// ============================================================================\n\nenum TicketStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum TicketPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nmodel SupportTicket {\n  id          String         @id @default(cuid())\n  subject     String\n  description String\n  status      TicketStatus   @default(OPEN)\n  priority    TicketPriority @default(MEDIUM)\n\n  // Who submitted the ticket (any User)\n  submittedById String\n  submittedBy   user   @relation(\"SubmittedTickets\", fields: [submittedById], references: [id])\n\n  // Which school this ticket belongs to (optional — superAdmin tickets have no school)\n  schoolId String?\n  school   School? @relation(fields: [schoolId], references: [id])\n\n  // Who is handling this ticket (SuperAdmin user)\n  assignedToId String?\n  assignedTo   user?   @relation(\"AssignedTickets\", fields: [assignedToId], references: [id])\n\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n  replies   TicketReply[]\n\n  @@index([submittedById])\n  @@index([schoolId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id       String @id @default(cuid())\n  ticketId String\n  authorId String\n  message  String\n\n  ticket SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  author user          @relation(fields: [authorId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\nmodel Club {\n  id                String   @id @default(cuid())\n  schoolId          String\n  name              String\n  description       String?\n  teacherInChargeId String?\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  school          School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  teacherInCharge Teacher?     @relation(fields: [teacherInChargeId], references: [id], onDelete: SetNull)\n  members         ClubMember[]\n\n  @@unique([name, schoolId])\n  @@index([schoolId])\n  @@index([teacherInChargeId])\n  @@map(\"clubs\")\n}\n\nmodel ClubMember {\n  id        String   @id @default(cuid())\n  clubId    String\n  studentId String\n  joinedAt  DateTime @default(now())\n  role      String? // e.g., President, Secretary\n\n  club    Club    @relation(fields: [clubId], references: [id], onDelete: Cascade)\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([clubId, studentId])\n  @@index([clubId])\n  @@index([studentId])\n  @@map(\"club_members\")\n}\n\nmodel PayrollRecord {\n  id            String        @id @default(cuid())\n  schoolId      String\n  month         Int // 1-12\n  year          Int\n  status        PayrollStatus @default(DRAFT)\n  totalGross    Decimal       @db.Decimal(15, 2)\n  totalNet      Decimal       @db.Decimal(15, 2)\n  totalTax      Decimal       @db.Decimal(15, 2)\n  totalSSNIT    Decimal       @db.Decimal(15, 2)\n  processedById String?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  academicYearId String?\n  termId         String?\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear? @relation(fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n  processedBy  user?         @relation(\"PayrollProcessedBy\", fields: [processedById], references: [id], onDelete: SetNull)\n  payslips     Payslip[]\n\n  @@unique([schoolId, month, year])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"payroll_records\")\n}\n\nmodel Payslip {\n  id              String  @id @default(cuid())\n  payrollRecordId String\n  schoolId        String\n  staffId         String?\n  teacherId       String?\n\n  basicSalary Decimal @db.Decimal(15, 2)\n  allowances  Decimal @default(0) @db.Decimal(15, 2)\n  grossSalary Decimal @db.Decimal(15, 2)\n\n  // Deductions\n  ssnitEmployee   Decimal @db.Decimal(15, 2) // 5.5%\n  ssnitEmployer   Decimal @db.Decimal(15, 2) // 13%\n  incomeTax       Decimal @db.Decimal(15, 2) // PAYE\n  otherDeductions Decimal @default(0) @db.Decimal(15, 2)\n\n  netSalary Decimal @db.Decimal(15, 2)\n\n  paymentMethod PaymentMethod @default(BANK_TRANSFER)\n  paymentStatus PaymentStatus @default(PENDING)\n  paidAt        DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  payrollRecord PayrollRecord @relation(fields: [payrollRecordId], references: [id], onDelete: Cascade)\n  school        School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  staff         Staff?        @relation(fields: [staffId], references: [id], onDelete: SetNull)\n  teacher       Teacher?      @relation(fields: [teacherId], references: [id], onDelete: SetNull)\n\n  @@index([payrollRecordId])\n  @@index([staffId])\n  @@index([teacherId])\n  @@map(\"payslips\")\n}\n\nenum PayrollStatus {\n  DRAFT\n  APPROVED\n  PAID\n  CANCELLED\n}\n\nenum DayOfWeek {\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n  SUNDAY\n}\n\nenum TimetableEntryType {\n  LESSON\n  BREAK\n  ACTIVITY\n}\n\nmodel Classroom {\n  id        String   @id @default(cuid())\n  schoolId  String\n  name      String\n  capacity  Int?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school           School           @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  timetableEntries TimetableEntry[]\n\n  @@unique([name, schoolId])\n  @@map(\"classrooms\")\n}\n\n/// Defines a reusable period (e.g. \"Period 1: 08:00–08:45\") with no day attached.\n/// departmentId = null means school-wide; set = department-specific schedule.\nmodel PeriodTemplate {\n  id           String  @id @default(cuid())\n  schoolId     String\n  /// null → applies to all departments; set → department-specific schedule\n  departmentId String?\n  name         String // \"Period 1\", \"Lunch Break\"\n  startTime    String // \"HH:mm\"\n  endTime      String // \"HH:mm\"\n  sortOrder    Int     @default(0)\n\n  school     School      @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department Department? @relation(\"DeptPeriodTemplates\", fields: [departmentId], references: [id], onDelete: Cascade)\n\n  @@unique([schoolId, departmentId, startTime, endTime])\n  @@index([schoolId, departmentId])\n  @@map(\"period_templates\")\n}\n\nmodel TimeSlot {\n  id           String    @id @default(cuid())\n  schoolId     String\n  /// null → school-wide slot; set → only appears on this department's timetable\n  departmentId String?\n  dayOfWeek    DayOfWeek\n  startTime    String // \"HH:mm\"\n  endTime      String // \"HH:mm\"\n  label        String? // e.g., \"Period 1\"\n\n  school           School           @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department       Department?      @relation(\"DeptTimeSlots\", fields: [departmentId], references: [id], onDelete: Cascade)\n  timetableEntries TimetableEntry[]\n\n  @@unique([schoolId, departmentId, dayOfWeek, startTime, endTime])\n  @@index([schoolId, departmentId])\n  @@map(\"time_slots\")\n}\n\nmodel TimetableEntry {\n  id             String             @id @default(cuid())\n  schoolId       String\n  classId        String?\n  departmentId   String?\n  /// LESSON = normal class, BREAK = lunch/recess, ACTIVITY = P.E./Worship/Library\n  type           TimetableEntryType @default(LESSON)\n  /// Human-readable label for breaks/activities e.g. \"Lunch\", \"Worship\"\n  label          String?\n  subjectId      String? // Optional: Breaks and Activities may not have a subject\n  teacherId      String? // Optional: Teacherless activities (P.E., Worship) allowed\n  timeSlotId     String\n  classroomId    String?\n  academicYearId String\n  termId         String?\n\n  school       School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  class        Class?       @relation(fields: [classId], references: [id], onDelete: Cascade)\n  department   Department?  @relation(fields: [departmentId], references: [id], onDelete: Cascade)\n  subject      Subject?     @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  teacher      Teacher?     @relation(fields: [teacherId], references: [id], onDelete: SetNull)\n  timeSlot     TimeSlot     @relation(fields: [timeSlotId], references: [id], onDelete: Cascade)\n  classroom    Classroom?   @relation(fields: [classroomId], references: [id], onDelete: SetNull)\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n\n  // Teacher conflict: one teacher can only be in one place per time slot (enforced at API layer for nullables)\n  @@unique([classroomId, timeSlotId, academicYearId])\n  // One class/dept can only have one entry per slot\n  @@unique([classId, timeSlotId, academicYearId])\n  @@unique([departmentId, timeSlotId, academicYearId])\n  @@index([classId])\n  @@index([departmentId])\n  @@index([teacherId])\n  @@index([timeSlotId])\n  @@map(\"timetable_entries\")\n}\n\nmodel AssessmentTemplateClass {\n  id         String @id @default(cuid())\n  templateId String\n  classId    String\n\n  template AssessmentTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  class    Class              @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  @@unique([templateId, classId])\n}\n\nmodel AssessmentExtension {\n  id         String   @id @default(cuid())\n  templateId String\n  classId    String\n  teacherId  String?\n  deadline   DateTime\n  reason     String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  template AssessmentTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  class    Class              @relation(fields: [classId], references: [id], onDelete: Cascade)\n  teacher  Teacher?           @relation(fields: [teacherId], references: [id], onDelete: SetNull)\n\n  @@unique([templateId, classId, teacherId])\n}\n\nmodel ReportCardSetClass {\n  id      String @id @default(cuid())\n  setId   String\n  classId String\n\n  set   ReportCardSet @relation(fields: [setId], references: [id], onDelete: Cascade)\n  class Class         @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  @@unique([setId, classId])\n}\n\nenum AssessmentScoreStatus {\n  DRAFT\n  SUBMITTED\n  REVIEWED\n  FINAL\n}\n"
}

